@inherits UmbracoViewPage<BlogFrontPage>
@{
    Layout = null;
}
<!doctype html>
<html lang="en">
<head>
    <meta charset="utf-8" />
    <meta name="viewport" content="width=device-width, initial-scale=1" />
    <meta name="description" content="Field notes on the Model Context Protocol and connected tools." />
    <title>MCP Journal | Tools work better together</title>
    <link rel="stylesheet" href="~/dist/site.css" asp-append-version="true" />
</head>
<body class="bg-[#f6f8f7] font-sans antialiased">
    <header class="bg-[#101b2a] text-white">
        <div class="mx-auto flex max-w-7xl items-center justify-between px-6 py-5 md:px-10">
            <a href="/" class="text-lg font-bold tracking-tight">MCP<span class="text-[#7fe3d1]">.</span> Journal</a>
            <a href="#stories" class="text-sm font-medium text-slate-300 transition hover:text-white">Explore stories <span aria-hidden="true">&darr;</span></a>
        </div>
    </header>
    <main>@await Html.GetBlockGridHtmlAsync(Model, "blocks")</main>
    <footer class="border-t border-slate-200 bg-white px-6 py-8 text-center text-sm text-slate-500">Made with Umbraco, blocks, and MCP.</footer>
</body>
</html>
=== Views/blogPostPage.cshtml
@using Umbraco.Bench.Umbraco.Models
@inherits UmbracoViewPage<BlogPostPage>
@{
    Layout = null;
    var frontUrl = Model.Parent<BlogFrontPage>()?.Url() ?? "/";
}
<!doctype html>
<html lang="en">
<head>
    <meta charset="utf-8" />
    <meta name="viewport" content="width=device-width, initial-scale=1" />
    <title>@Model.Name | MCP Journal</title>
    <link rel="stylesheet" href="~/dist/site.css" asp-append-version="true" />
</head>
<body class="bg-[#f6f8f7] font-sans antialiased">
    <header class="bg-[#101b2a] text-white">
        <div class="mx-auto flex max-w-7xl items-center justify-between px-6 py-5 md:px-10">
            <a href="@frontUrl" class="text-lg font-bold tracking-tight">MCP<span class="text-[#7fe3d1]">.</span> Journal</a>
            <a href="@frontUrl#stories" class="text-sm font-medium text-slate-300 transition hover:text-white">&larr; All stories</a>
        </div>
    </header>
    <main>@await Html.GetBlockGridHtmlAsync(Model, "blocks")</main>
    <footer class="border-t border-slate-200 bg-white px-6 py-8 text-center text-sm text-slate-500"><a href="@frontUrl#stories" class="font-semibold text-teal-700 hover:underline">&larr; Back to stories</a></footer>
</body>
</html>

